messages.body:
[
  {
    "type": "function",
    "function": {
      "name": "readStoryboardContext",
      "description": "Read the screenplay, characters, scenes, and props for storyboard breakdown.",
      "parameters": {
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "properties": {},
        "additionalProperties": false,
        "required": []
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "readImage",
      "description": "Read a local image (must be a path under static/, e.g. an asset image_url or an uploaded original) with a vision-capable text model and answer a question about it. Use it to find what is actually drawn in a map/diagram/photo (place names, labels, pixel boxes) before writing prompts or semantics. Returns { unsupported: true } when no vision-capable text config exists — then fall back to text-only reasoning and say so. Ask for concrete, verifiable facts (text labels and their pixel boxes); do NOT ask the model to trace polylines or polygons, it is unreliable. Any pixel coordinates in the answer are in the returned image.{width,height} frame (the resized image that was sent); image.source_width/source_height give the original size for rescaling.",
      "parameters": {
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "图片路径，必须是 static/ 下的现存文件，例如 static/uploads/xxx.png"
          },
          "question": {
            "type": "string",
            "description": "要问这张图什么；越具体越好（例如「列出图上可读的地名及其像素框」）"
          },
          "max_side": {
            "description": "送进模型前把长边缩到多少像素，默认 1600\nconstraints: greater than or equal to 256, lower than or equal to 2048",
            "anyOf": [
              {
                "description": "送进模型前把长边缩到多少像素，默认 1600\nconstraints: greater than or equal to 256, lower than or equal to 2048",
                "type": "integer"
              },
              {
                "type": "null"
              }
            ]
          },
          "expect_json": {
            "description": "为 true 时解析返回里的第一个 JSON；解析失败会原样回文本并标 json_error",
            "anyOf": [
              {
                "description": "为 true 时解析返回里的第一个 JSON；解析失败会原样回文本并标 json_error",
                "type": "boolean"
              },
              {
                "type": "null"
              }
            ]
          }
        },
        "required": [
          "path",
          "question",
          "max_side",
          "expect_json"
        ],
        "additionalProperties": false,
        "x-optional": [
          "max_side",
          "expect_json"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "updateStoryboard",
      "description": "Save only the fields this request permits (the requested storyboard prompts, or the shot design card). Other storyboard fields are never writable with this tool.",
      "parameters": {
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "properties": {
          "storyboard_id": {
            "type": "number"
          },
          "design_card": {
            "description": "Documentary design card, including the chosen combo and optional suggestion.",
            "anyOf": [
              {
                "type": "object",
                "properties": {
                  "combo": {
                    "description": "Segment combination: A layer only, B generated only, C layer then generated, D generated then layer.",
                    "anyOf": [
                      {
                        "description": "Segment combination: A layer only, B generated only, C layer then generated, D generated then layer.",
                        "type": "string"
                      },
                      {
                        "type": "null"
                      }
                    ]
                  },
                  "info_points": {
                    "description": "What the viewer must understand after this shot. At most 12.\nconstraints: maximum length 12",
                    "anyOf": [
                      {
                        "type": "array",
                        "items": {
                          "type": "object",
                          "properties": {
                            "id": {
                              "description": "Stable short id such as ip1.",
                              "anyOf": [
                                {
                                  "description": "Stable short id such as ip1.",
                                  "type": "string"
                                },
                                {
                                  "type": "null"
                                }
                              ]
                            },
                            "text": {
                              "type": "string",
                              "description": "One piece of information the viewer must get from this shot."
                            },
                            "via": {
                              "type": "string",
                              "enum": [
                                "layer",
                                "generated",
                                "narration_only"
                              ],
                              "description": "How this point is delivered: 'layer' drawn on the layer segment, 'generated' shown in the generated video segment, 'narration_only' carried by the narration alone."
                            }
                          },
                          "required": [
                            "text",
                            "via",
                            "id"
                          ],
                          "additionalProperties": false,
                          "x-optional": [
                            "id"
                          ]
                        }
                      },
                      {
                        "type": "null"
                      }
                    ]
                  },
                  "budget": {
                    "description": "Segment budget. layer_s + gen_s must be at least the estimated narration duration (4.5 spoken characters per second plus 0.8s tail).",
                    "anyOf": [
                      {
                        "type": "object",
                        "properties": {
                          "layer_s": {
                            "description": "Planned length of the layer segment in seconds, at most 30. null when this shot has no layer segment.",
                            "anyOf": [
                              {
                                "type": "number"
                              },
                              {
                                "type": "null"
                              }
                            ]
                          },
                          "gen_s": {
                            "description": "Planned length of the generated segment in seconds, at most 15. null when this shot has no generated segment.",
                            "anyOf": [
                              {
                                "type": "number"
                              },
                              {
                                "type": "null"
                              }
                            ]
                          }
                        },
                        "required": [
                          "layer_s",
                          "gen_s"
                        ],
                        "additionalProperties": false,
                        "x-optional": [
                          "layer_s",
                          "gen_s"
                        ]
                      },
                      {
                        "type": "null"
                      }
                    ]
                  },
                  "layer_plan": {
                    "description": "Layer segment plan. Required when the shot has a layer segment (combos A, C, D).",
                    "anyOf": [
                      {
                        "type": "object",
                        "properties": {
                          "base": {
                            "description": "Base image of the layer segment.",
                            "anyOf": [
                              {
                                "type": "object",
                                "properties": {
                                  "kind": {
                                    "type": "string",
                                    "enum": [
                                      "asset",
                                      "inherit_prev"
                                    ],
                                    "description": "'asset' picks a verified faithful original / generated image; 'inherit_prev' continues the previous shot's base image."
                                  },
                                  "asset_kind": {
                                    "anyOf": [
                                      {
                                        "type": "string",
                                        "enum": [
                                          "character",
                                          "scene",
                                          "prop"
                                        ]
                                      },
                                      {
                                        "type": "null"
                                      }
                                    ]
                                  },
                                  "asset_id": {
                                    "anyOf": [
                                      {
                                        "type": "number"
                                      },
                                      {
                                        "type": "null"
                                      }
                                    ]
                                  }
                                },
                                "required": [
                                  "kind",
                                  "asset_kind",
                                  "asset_id"
                                ],
                                "additionalProperties": false,
                                "x-optional": [
                                  "asset_kind",
                                  "asset_id"
                                ]
                              },
                              {
                                "type": "null"
                              }
                            ]
                          },
                          "must_mark": {
                            "description": "Elements this shot promises to mark. Use real asset semantics only; when an annotation is missing, leave semantic_id and name empty and retain the planned layer as awaiting annotation.\nconstraints: maximum length 20",
                            "anyOf": [
                              {
                                "type": "array",
                                "items": {
                                  "type": "object",
                                  "properties": {
                                    "asset_id": {
                                      "type": "number",
                                      "description": "Asset id the annotated element lives on (prop id for maps/documents)."
                                    },
                                    "semantic_id": {
                                      "type": "string",
                                      "description": "Stable id (or exact name) of the annotated element, copied verbatim from the semantics list in read_storyboard_context."
                                    },
                                    "name": {
                                      "description": "Human readable name of that element.",
                                      "anyOf": [
                                        {
                                          "description": "Human readable name of that element.",
                                          "type": "string"
                                        },
                                        {
                                          "type": "null"
                                        }
                                      ]
                                    }
                                  },
                                  "required": [
                                    "asset_id",
                                    "semantic_id",
                                    "name"
                                  ],
                                  "additionalProperties": false,
                                  "x-optional": [
                                    "name"
                                  ]
                                }
                              },
                              {
                                "type": "null"
                              }
                            ]
                          },
                          "planned_layers": {
                            "description": "Rough layer plan. A map without any layer is just a prop being panned over.\nconstraints: maximum length 40",
                            "anyOf": [
                              {
                                "type": "array",
                                "items": {
                                  "type": "object",
                                  "properties": {
                                    "type": {
                                      "type": "string",
                                      "enum": [
                                        "polygon",
                                        "polyline",
                                        "marker",
                                        "label",
                                        "card",
                                        "image"
                                      ],
                                      "description": "Layer type drawn on top of the base image."
                                    },
                                    "text": {
                                      "description": "Text shown by this layer (label/card content).",
                                      "anyOf": [
                                        {
                                          "description": "Text shown by this layer (label/card content).",
                                          "type": "string"
                                        },
                                        {
                                          "type": "null"
                                        }
                                      ]
                                    },
                                    "anchor": {
                                      "description": "Annotated element this layer is drawn from.",
                                      "anyOf": [
                                        {
                                          "type": "object",
                                          "properties": {
                                            "asset_id": {
                                              "type": "number",
                                              "description": "Asset id the annotated element lives on (prop id for maps/documents)."
                                            },
                                            "semantic_id": {
                                              "type": "string",
                                              "description": "Stable id (or exact name) of the annotated element, copied verbatim from the semantics list in read_storyboard_context."
                                            },
                                            "name": {
                                              "description": "Human readable name of that element.",
                                              "anyOf": [
                                                {
                                                  "description": "Human readable name of that element.",
                                                  "type": "string"
                                                },
                                                {
                                                  "type": "null"
                                                }
                                              ]
                                            }
                                          },
                                          "required": [
                                            "asset_id",
                                            "semantic_id",
                                            "name"
                                          ],
                                          "additionalProperties": false,
                                          "x-optional": [
                                            "name"
                                          ]
                                        },
                                        {
                                          "type": "null"
                                        }
                                      ]
                                    },
                                    "at_s": {
                                      "description": "Seconds from the start of the layer segment when this layer appears.",
                                      "anyOf": [
                                        {
                                          "description": "Seconds from the start of the layer segment when this layer appears.",
                                          "type": "number"
                                        },
                                        {
                                          "type": "null"
                                        }
                                      ]
                                    }
                                  },
                                  "required": [
                                    "type",
                                    "text",
                                    "anchor",
                                    "at_s"
                                  ],
                                  "additionalProperties": false,
                                  "x-optional": [
                                    "text",
                                    "anchor",
                                    "at_s"
                                  ]
                                }
                              },
                              {
                                "type": "null"
                              }
                            ]
                          }
                        },
                        "required": [
                          "base",
                          "must_mark",
                          "planned_layers"
                        ],
                        "additionalProperties": false,
                        "x-optional": [
                          "base",
                          "must_mark",
                          "planned_layers"
                        ]
                      },
                      {
                        "type": "null"
                      }
                    ]
                  },
                  "gen_plan": {
                    "description": "Generated segment plan. Required when the shot has a generated segment (combos B, C, D).",
                    "anyOf": [
                      {
                        "type": "object",
                        "properties": {
                          "reference_assets": {
                            "description": "Assets the keyframe prompts must reference with @名字.\nconstraints: maximum length 20",
                            "anyOf": [
                              {
                                "type": "array",
                                "items": {
                                  "type": "object",
                                  "properties": {
                                    "kind": {
                                      "type": "string",
                                      "enum": [
                                        "character",
                                        "scene",
                                        "prop"
                                      ]
                                    },
                                    "id": {
                                      "type": "number"
                                    },
                                    "name": {
                                      "anyOf": [
                                        {
                                          "type": "string"
                                        },
                                        {
                                          "type": "null"
                                        }
                                      ]
                                    }
                                  },
                                  "required": [
                                    "kind",
                                    "id",
                                    "name"
                                  ],
                                  "additionalProperties": false,
                                  "x-optional": [
                                    "name"
                                  ]
                                }
                              },
                              {
                                "type": "null"
                              }
                            ]
                          },
                          "first": {
                            "description": "One sentence for the first story keyframe. Omit when the junction frame locks it (combo C).",
                            "anyOf": [
                              {
                                "description": "One sentence for the first story keyframe. Omit when the junction frame locks it (combo C).",
                                "type": "string"
                              },
                              {
                                "type": "null"
                              }
                            ]
                          },
                          "mid": {
                            "description": "One sentence for the optional middle story keyframe.",
                            "anyOf": [
                              {
                                "description": "One sentence for the optional middle story keyframe.",
                                "type": "string"
                              },
                              {
                                "type": "null"
                              }
                            ]
                          },
                          "last": {
                            "description": "One sentence for the last story keyframe. Omit when the junction frame locks it (combo D).",
                            "anyOf": [
                              {
                                "description": "One sentence for the last story keyframe. Omit when the junction frame locks it (combo D).",
                                "type": "string"
                              },
                              {
                                "type": "null"
                              }
                            ]
                          }
                        },
                        "required": [
                          "reference_assets",
                          "first",
                          "mid",
                          "last"
                        ],
                        "additionalProperties": false,
                        "x-optional": [
                          "reference_assets",
                          "first",
                          "mid",
                          "last"
                        ]
                      },
                      {
                        "type": "null"
                      }
                    ]
                  },
                  "rationale": {
                    "description": "Why this plan expresses the narration; mention the neighbouring shots when this shot continues them.",
                    "anyOf": [
                      {
                        "description": "Why this plan expresses the narration; mention the neighbouring shots when this shot continues them.",
                        "type": "string"
                      },
                      {
                        "type": "null"
                      }
                    ]
                  },
                  "suggested_combo": {
                    "description": "Suggested segment combination for display.",
                    "anyOf": [
                      {
                        "description": "Suggested segment combination for display.",
                        "type": "string",
                        "enum": [
                          "A",
                          "B",
                          "C",
                          "D"
                        ]
                      },
                      {
                        "type": "null"
                      }
                    ]
                  }
                },
                "required": [
                  "combo",
                  "info_points",
                  "budget",
                  "layer_plan",
                  "gen_plan",
                  "rationale",
                  "suggested_combo"
                ],
                "additionalProperties": false,
                "x-optional": [
                  "combo",
                  "info_points",
                  "budget",
                  "layer_plan",
                  "gen_plan",
                  "rationale",
                  "suggested_combo"
                ]
              },
              {
                "type": "null"
              }
            ]
          }
        },
        "required": [
          "storyboard_id",
          "design_card"
        ],
        "additionalProperties": false,
        "x-optional": [
          "design_card"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "mastra_workspace_read_file",
      "description": "Read a file from the workspace filesystem. Text files come back as text — use offset/limit to read a line range from large files. Supported media files come back as a native file part you can view directly. Other binary files return only their metadata (path, size, mime type) since their raw contents are not useful to read.",
      "parameters": {
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "The path to the file to read (e.g., \"data/config.json\")"
          },
          "offset": {
            "description": "Line number to start reading from (1-indexed). Only used when reading text files; ignored for media and other binary files. Defaults to line 1 if omitted.\nconstraints: greater than or equal to 1",
            "anyOf": [
              {
                "description": "Line number to start reading from (1-indexed). Only used when reading text files; ignored for media and other binary files. Defaults to line 1 if omitted.\nconstraints: greater than or equal to 1",
                "type": "integer"
              },
              {
                "type": "null"
              }
            ]
          },
          "limit": {
            "description": "Maximum number of lines to read. Only used when reading text files; ignored for media and other binary files. Defaults to the end of the file if omitted.\nconstraints: greater than or equal to 1",
            "anyOf": [
              {
                "description": "Maximum number of lines to read. Only used when reading text files; ignored for media and other binary files. Defaults to the end of the file if omitted.\nconstraints: greater than or equal to 1",
                "type": "integer"
              },
              {
                "type": "null"
              }
            ]
          },
          "showLineNumbers": {
            "default": true,
            "description": "Prefix each line with its line number. Only used when reading text files; ignored for media and other binary files. Defaults to true if omitted.",
            "anyOf": [
              {
                "default": true,
                "description": "Prefix each line with its line number. Only used when reading text files; ignored for media and other binary files. Defaults to true if omitted.",
                "type": "boolean"
              },
              {
                "type": "null"
              }
            ]
          },
          "encoding": {
            "description": "Usually omit this — text files and supported media are handled automatically. Pass `base64` or `hex` to get the file's raw bytes encoded as text when you need to inspect an unsupported binary file that would otherwise only return metadata (e.g. checking a file header or magic bytes).",
            "anyOf": [
              {
                "description": "Usually omit this — text files and supported media are handled automatically. Pass `base64` or `hex` to get the file's raw bytes encoded as text when you need to inspect an unsupported binary file that would otherwise only return metadata (e.g. checking a file header or magic bytes).",
                "type": "string",
                "enum": [
                  "utf-8",
                  "utf8",
                  "base64",
                  "hex",
                  "binary"
                ]
              },
              {
                "type": "null"
              }
            ]
          }
        },
        "required": [
          "path",
          "offset",
          "limit",
          "showLineNumbers",
          "encoding"
        ],
        "additionalProperties": false,
        "x-optional": [
          "offset",
          "limit",
          "showLineNumbers",
          "encoding"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "mastra_workspace_write_file",
      "description": "Write content to a file in the workspace filesystem. Creates parent directories if needed.",
      "parameters": {
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "The path where to write the file (e.g., \"data/output.txt\")"
          },
          "content": {
            "type": "string",
            "description": "The content to write to the file"
          },
          "overwrite": {
            "default": true,
            "description": "Whether to overwrite the file if it already exists",
            "anyOf": [
              {
                "default": true,
                "description": "Whether to overwrite the file if it already exists",
                "type": "boolean"
              },
              {
                "type": "null"
              }
            ]
          }
        },
        "required": [
          "path",
          "content",
          "overwrite"
        ],
        "additionalProperties": false,
        "x-optional": [
          "overwrite"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "mastra_workspace_edit_file",
      "description": "Edit a file by replacing specific text. The old_string must match exactly and be unique in the file.\n\nUsage:\n- Read the file first to get the exact text to replace.\n- By default, read file output includes line number prefixes (e.g., \"     1→\"). Ensure you preserve the exact indentation as it appears AFTER the arrow. Never include any part of the line number prefix in old_string or new_string.\n- Include enough surrounding context (multiple lines) to make old_string unique. If it still isn't unique, include more lines.\n- Use replace_all only when intentionally replacing all occurrences.",
      "parameters": {
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "The path to the file to edit"
          },
          "old_string": {
            "type": "string",
            "description": "The exact text to find and replace. Must be unique in the file."
          },
          "new_string": {
            "type": "string",
            "description": "The text to replace old_string with"
          },
          "replace_all": {
            "default": false,
            "description": "If true, replace all occurrences. If false (default), old_string must be unique.",
            "anyOf": [
              {
                "default": false,
                "description": "If true, replace all occurrences. If false (default), old_string must be unique.",
                "type": "boolean"
              },
              {
                "type": "null"
              }
            ]
          }
        },
        "required": [
          "path",
          "old_string",
          "new_string",
          "replace_all"
        ],
        "additionalProperties": false,
        "x-optional": [
          "replace_all"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "mastra_workspace_list_files",
      "description": "List files and directories in the workspace filesystem.\nReturns a compact tab-indented listing for efficient token usage.\nOptions mirror common tree command flags for familiarity.\n\nExamples:\n- List workspace root: { path: \".\" }\n- Deep listing: { path: \"src\", maxDepth: 5 }\n- Directories only: { path: \".\", dirsOnly: true }\n- Exclude node_modules: { path: \".\", exclude: \"node_modules\" }\n- Find TypeScript files: { path: \"src\", pattern: \"**/*.ts\" }\n- Find config files: { path: \".\", pattern: \"*.config.{js,ts}\" }\n- Multiple patterns: { path: \".\", pattern: [\"**/*.ts\", \"**/*.tsx\"] }\n\nTo list ALL files, omit the pattern parameter — do NOT pass pattern: \"*\".",
      "parameters": {
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "properties": {
          "path": {
            "default": ".",
            "description": "Directory path to list",
            "anyOf": [
              {
                "default": ".",
                "description": "Directory path to list",
                "type": "string"
              },
              {
                "type": "null"
              }
            ]
          },
          "maxDepth": {
            "default": 2,
            "description": "Maximum depth to descend (default: 2). Similar to tree -L flag.",
            "anyOf": [
              {
                "default": 2,
                "description": "Maximum depth to descend (default: 2). Similar to tree -L flag.",
                "type": "number"
              },
              {
                "type": "null"
              }
            ]
          },
          "showHidden": {
            "default": false,
            "description": "Show hidden files starting with \".\" (default: false). Similar to tree -a flag.",
            "anyOf": [
              {
                "default": false,
                "description": "Show hidden files starting with \".\" (default: false). Similar to tree -a flag.",
                "type": "boolean"
              },
              {
                "type": "null"
              }
            ]
          },
          "dirsOnly": {
            "default": false,
            "description": "List directories only, no files (default: false). Similar to tree -d flag.",
            "anyOf": [
              {
                "default": false,
                "description": "List directories only, no files (default: false). Similar to tree -d flag.",
                "type": "boolean"
              },
              {
                "type": "null"
              }
            ]
          },
          "exclude": {
            "description": "Pattern to exclude (e.g., \"node_modules\"). Similar to tree -I flag.",
