      "name": "readImage",
      "description": "Read a local image (must be a path under static/, e.g. an asset image_url or an uploaded original) with a vision-capable text model and answer a question about it. Use it to find what is actually drawn in a map/diagram/photo (place names, labels, pixel boxes) before writing prompts or semantics. Returns { unsupported: true } when no vision-capable text config exists — then fall back to text-only reasoning and say so. Ask for concrete, verifiable facts (text labels and their pixel boxes); do NOT ask the model to trace polylines or polygons, it is unreliable. Any pixel coordinates in the answer are in the returned image.{width,height} frame (the resized image that was sent); image.source_width/source_height give the original size for rescaling.",
      "parameters": {
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "图片路径，必须是 static/ 下的现存文件，例如 static/uploads/xxx.png"
          },
          "question": {
            "type": "string",
            "description": "要问这张图什么；越具体越好（例如「列出图上可读的地名及其像素框」）"
          },
          "max_side": {
            "description": "送进模型前把长边缩到多少像素，默认 1600\nconstraints: greater than or equal to 256, lower than or equal to 2048",
            "anyOf": [
              {
                "description": "送进模型前把长边缩到多少像素，默认 1600\nconstraints: greater than or equal to 256, lower than or equal to 2048",
                "type": "integer"
              },
              {
                "type": "null"
              }
            ]
          },
          "expect_json": {
            "description": "为 true 时解析返回里的第一个 JSON；解析失败会原样回文本并标 json_error",
            "anyOf": [
              {
                "description": "为 true 时解析返回里的第一个 JSON；解析失败会原样回文本并标 json_error",
                "type": "boolean"
              },
              {
                "type": "null"
              }
            ]
          }
